INPUT_DIR = '/inputs'
import json
from decimal import Decimal, ROUND_HALF_UP
from datetime import date

def load(name):
    try:
        with open(f"{INPUT_DIR}/{name}", encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError:
        return None

def dec(v):
    if v is None:
        return None
    if isinstance(v, str) and v.strip().lower() == "unreadable":
        return None
    try:
        return Decimal(str(v))
    except Exception:
        return None

def cents(d):
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

def tenth(d):
    return d.quantize(Decimal("0.1"), rounding=ROUND_HALF_UP)

def money_str(d):
    return None if d is None else format(cents(d), "f")

def kl_str(d):
    return None if d is None else format(tenth(d), "f")

bill = load("bill.json") or {}
tariff = load("tariff.json") or {}
history = load("history.json")

subtotal = None
vat = None
total = None

consumption = dec(bill.get("consumption_kl"))
tiers = tariff.get("water_tiers")
vat_rate = dec(tariff.get("vat_rate"))

if consumption is not None and isinstance(tiers, list) and vat_rate is not None:
    lines = []
    ok = True
    for t in tiers:
        f = dec(t.get("from_kl"))
        to = t.get("to_kl")
        to_d = dec(to) if to is not None else None
        rate = dec(t.get("rate_per_kl"))
        if f is None or rate is None:
            ok = False
            break
        upper = to_d if to_d is not None else consumption
        band = min(consumption, upper) - f
        if band < 0:
            band = Decimal(0)
        lines.append(cents(band * rate))
    if ok:
        fixed = tariff.get("fixed_charges") or []
        for fc in fixed:
            amt = dec(fc.get("amount"))
            if amt is None:
                ok = False
                break
            lines.append(cents(amt))
    if ok:
        subtotal = sum(lines, Decimal(0))
        vat = cents(subtotal * vat_rate)
        total = subtotal + vat

normal_kl = None
normal_avg = None
if history is not None:
    if str(history.get("account_number")) == str(bill.get("account_number")):
        prev = history.get("previous_bills") or []
        vals = []
        for p in prev:
            c = dec(p.get("consumption_kl"))
            if c is not None:
                vals.append(c)
        if len(vals) >= 2:
            normal_avg = sum(vals, Decimal(0)) / Decimal(len(vals))
            normal_kl = tenth(normal_avg)

period_days = None
start = bill.get("billing_period", {}).get("start")
end = bill.get("billing_period", {}).get("end")
try:
    sd = date.fromisoformat(start)
    ed = date.fromisoformat(end)
    period_days = (ed - sd).days + 1
    if period_days < 0:
        period_days = None
except Exception:
    period_days = None

outage_days = None
if period_days is not None and history is not None:
    log = history.get("outage_log") or []
    seen = set()
    for e in log:
        if e.get("supply") == "none":
            try:
                d = date.fromisoformat(e.get("date"))
            except Exception:
                continue
            if sd <= d <= ed:
                seen.add(d)
    outage_days = len(seen)

supplied_days = None
if period_days is not None and outage_days is not None:
    supplied_days = period_days - outage_days

implied_kl = None
if normal_avg is not None and supplied_days is not None and period_days:
    implied_kl = tenth(normal_avg * Decimal(supplied_days) / Decimal(period_days))

result = {
    "subtotal": money_str(subtotal),
    "vat": money_str(vat),
    "total": money_str(total),
    "normal_kl": kl_str(normal_kl),
    "period_days": period_days,
    "outage_days": outage_days,
    "supplied_days": supplied_days,
    "implied_kl": kl_str(implied_kl),
}
print(json.dumps(result))
